const crypto = require('crypto');
const item = $input.item.json;
const headers = item.headers || {};
const raw = typeof item.body === 'string' ? item.body : (item.rawBody || '');
const secret = $getWorkflowStaticData('global').klassappMarksSecret || '';
if (!secret || !raw) {
  return { json: { ok: false, reason: 'missing raw body or secret' } };
}
const given = String(headers['x-klassapp-signature'] || headers['X-KlassApp-Signature'] || '');
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
const givenBuf = Buffer.from(given);
const expectedBuf = Buffer.from(expected);
const match = givenBuf.length === expectedBuf.length && crypto.timingSafeEqual(givenBuf, expectedBuf);
let payload = {};
try { payload = JSON.parse(raw); } catch (e) { payload = {}; }
const now = Math.floor(Date.now() / 1000);
const stamp = Number(payload.timestamp || 0);
const headerStamp = Number(headers['x-klassapp-timestamp'] || headers['X-KlassApp-Timestamp'] || 0);
const fresh = stamp > 0 && stamp === headerStamp && Math.abs(now - stamp) <= 600;
const countsOnly = payload.event === 'marks.released' && payload.learners !== undefined && payload.missing !== undefined && payload.absent !== undefined;
if (!match || !fresh || !countsOnly) {
  return { json: { ok: false, reason: 'rejected' } };
}
return { json: { ok: true, release_id: payload.release_id, learners: payload.learners, classes: payload.classes, subjects: payload.subjects, missing: payload.missing, absent: payload.absent } };
